def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    line = set()

    # Draw the full segment between each aligned pair of markers.
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            line.update((r, c) for c in range(min(cols), max(cols) + 1))
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            line.update((r, c) for r in range(min(rows), max(rows) + 1))

    # Find maximal solid rectangles of 2s. Rectangles may touch at their edges,
    # so treating every connected region as one object would merge some objects.
    rects = set()
    for top in range(h):
        common = [True] * w
        for bottom in range(top, h):
            for c in range(w):
                common[c] = common[c] and grid[bottom][c] == 2
            c = 0
            while c < w:
                if not common[c]:
                    c += 1
                    continue
                left = c
                while c < w and common[c]:
                    c += 1
                right = c - 1

                can_extend_up = top > 0 and all(grid[top - 1][x] == 2 for x in range(left, right + 1))
                can_extend_down = bottom + 1 < h and all(grid[bottom + 1][x] == 2 for x in range(left, right + 1))
                if not can_extend_up and not can_extend_down:
                    rects.add((top, left, bottom, right))

    assigned = set()
    for top, left, bottom, right in sorted(
        rects, key=lambda box: (box[2] - box[0] + 1) * (box[3] - box[1] + 1), reverse=True
    ):
        cells = [(r, c) for r in range(top, bottom + 1) for c in range(left, right + 1)
                 if grid[r][c] == 2 and (r, c) not in assigned]
        if not cells:
            continue
        if any(cell in line for cell in cells):
            for r, c in cells:
                out[r][c] = 1
        assigned.update(cells)

    for r, c in line:
        out[r][c] = 1
    return out
